        .filter((item) => applies(item, ctx))
        .sort((a, b) => ctx.specificity(b) - ctx.specificity(a) || ctx.trackRecord(b).value - ctx.trackRecord(a).value)
        .slice(0, ctx.limit),
    ),
  )
  .recalledBy(drafter)
  .recordedBy(H.operator);

const timeToBreach = H.policy.order('time-to-breach', (ctx) => ({
