declare module 'harness-dsl' {
  import { z } from 'zod';
  import type {
    Ref,
    Ledger,
    Store,
    MemoryStore,
    Meter,
    Runner,
    Workspace,
    Observer,
    Transport,
    Producer,
    Account,
    Model,
    Metrics,
    PolicyContext,
    Rate,
    Skeleton,
    ControlApi,
  } from 'harness-dsl/kernel';

  export type {
    Ref,
    Ledger,
    Store,
    MemoryStore,
    Meter,
    Runner,
    Workspace,
    Observer,
    Transport,
    Producer,
    Account,
    Model,
    Metrics,
    PolicyContext,
    Rate,
    Skeleton,
  } from 'harness-dsl/kernel';

  export type Schema<T> = z.ZodType<T, unknown>;

  export interface Named {
    readonly name: string;
