  { name: 'api', url: 'https://api.internal/health' },
  { name: 'queue', url: 'https://queue.internal/health' },
];
const databases = [
  { database: 'orders', host: 'db-a' },
  { database: 'billing', host: 'db-b' },
];
const domains = [
